import 'package:flutter/material.dart';
import 'package:intl/intl.dart';
import '../models/models.dart';
import '../services/storage_service.dart';
import '../widgets/app_card.dart';

const expenseCategories=['Alimentação','Transporte','Moradia','Lazer','Educação','Saúde','Compras','Outros'];
const incomeCategories=['Salário','Freelance','Investimentos','Outros'];

class FinanceScreen extends StatefulWidget{const FinanceScreen({super.key});@override State<FinanceScreen> createState()=>_FinanceScreenState();}
class _FinanceScreenState extends State<FinanceScreen>{
  List<MoneyTransaction> items=[];DateTime month=DateTime(DateTime.now().year,DateTime.now().month);bool loading=true;
  @override void initState(){super.initState();_load();}
  Future<void> _load()async{items=(await StorageService.read('finance')).map(MoneyTransaction.fromJson).toList();_overdue();loading=false;if(mounted)setState((){});}
  void _overdue(){final now=DateTime.now();for(final x in items){final d=DateTime.tryParse(x.dueDate);if(d!=null&&!x.isPaid&&!x.isCancelled&&d.isBefore(DateTime(now.year,now.month,now.day)))x.paymentStatus='overdue';}}
  Future<void> _save()=>StorageService.write('finance',items.map((e)=>e.toJson()).toList());
  String _money(double v)=>'R\$ ${v.toStringAsFixed(2).replaceAll('.',',')}';
  String _key(DateTime d)=>DateFormat('yyyy-MM').format(d);
  List<MoneyTransaction> _month(DateTime d)=>items.where((x)=>x.date.startsWith(_key(d))&&!x.isCancelled).toList();
  double _sum(Iterable<MoneyTransaction> xs,bool income,{bool paid=false})=>xs.where((x)=>x.income==income&&(!paid||x.isPaid)).fold(0.0,(s,x)=>s+x.amount);
  double _balance()=>items.where((x)=>x.isPaid&&!x.isCancelled).fold(0.0,(s,x)=>s+(x.income?x.amount:-x.amount));
  double _committed(DateTime d)=>_month(d).where((x)=>!x.income&&!x.isPaid).fold(0.0,(s,x)=>s+x.amount);

  Future<void> _addMenu()async{final choice=await showModalBottomSheet<String>(context:context,builder:(ctx)=>SafeArea(child:Column(mainAxisSize:MainAxisSize.min,children:[ListTile(title:const Text('Nova entrada'),onTap:()=>Navigator.pop(ctx,'income')),ListTile(title:const Text('Nova despesa'),onTap:()=>Navigator.pop(ctx,'expense')),ListTile(title:const Text('Compra parcelada'),onTap:()=>Navigator.pop(ctx,'installment')),ListTile(title:const Text('Despesa recorrente'),onTap:()=>Navigator.pop(ctx,'recurring'))])));if(choice=='income')await _single(true);if(choice=='expense')await _single(false);if(choice=='installment')await _installment();if(choice=='recurring')await _recurring();}

  Future<void> _single(bool income)async{final desc=TextEditingController();final amount=TextEditingController();String category=income?'Salário':'Outros';String status='paid';final categories=income?incomeCategories:expenseCategories;final ok=await showDialog<bool>(context:context,builder:(ctx)=>AlertDialog(title:Text(income?'Nova entrada':'Nova despesa'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:desc,decoration:const InputDecoration(labelText:'Descrição')),TextField(controller:amount,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Valor',prefixText:'R\$ ')),DropdownButtonFormField<String>(initialValue:category,items:categories.map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v){if(v!=null)category=v;},decoration:const InputDecoration(labelText:'Categoria')),if(!income)DropdownButtonFormField<String>(initialValue:status,items:const[DropdownMenuItem(value:'paid',child:Text('Pago/realizado')),DropdownMenuItem(value:'pending',child:Text('Previsto'))],onChanged:(v){if(v!=null)status=v;},decoration:const InputDecoration(labelText:'Status'))]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('CANCELAR')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('SALVAR'))]));final v=double.tryParse(amount.text.replaceAll(',','.'));if(ok!=true||desc.text.trim().isEmpty||v==null||v<=0)return;final d=DateFormat('yyyy-MM-dd').format(DateTime.now());items.add(MoneyTransaction(id:DateTime.now().microsecondsSinceEpoch.toString(),date:d,description:desc.text.trim(),category:category,amount:v,income:income,paymentStatus:income?'paid':status,dueDate:d,paidDate:status=='paid'?d:null));await _save();if(mounted)setState((){});}

  Future<void> _installment()async{final desc=TextEditingController();final total=TextEditingController();final count=TextEditingController(text:'2');String category='Outros';final ok=await showDialog<bool>(context:context,builder:(ctx)=>AlertDialog(title:const Text('Compra parcelada'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:desc,decoration:const InputDecoration(labelText:'Descrição')),TextField(controller:total,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Valor total',prefixText:'R\$ ')),TextField(controller:count,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Quantidade de parcelas')),DropdownButtonFormField<String>(initialValue:category,items:expenseCategories.map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v){if(v!=null)category=v;},decoration:const InputDecoration(labelText:'Categoria'))]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('CANCELAR')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('CRIAR'))]));final value=double.tryParse(total.text.replaceAll(',','.'));final n=int.tryParse(count.text);if(ok!=true||desc.text.trim().isEmpty||value==null||value<=0||n==null||n<2)return;final group=DateTime.now().microsecondsSinceEpoch.toString();final each=value/n;double used=0;for(var i=1;i<=n;i++){final due=DateTime(DateTime.now().year,DateTime.now().month+i-1,DateTime.now().day);final amount=i==n?double.parse((value-used).toStringAsFixed(2)):double.parse(each.toStringAsFixed(2));used+=amount;final d=DateFormat('yyyy-MM-dd').format(due);final paid=due.isBefore(DateTime.now())||DateUtils.isSameDay(due,DateTime.now());items.add(MoneyTransaction(id:'$group-$i',date:d,description:desc.text.trim(),category:category,amount:amount,income:false,paymentStatus:paid?'paid':'pending',isInstallment:true,installmentGroupId:group,totalInstallments:n,installmentNumber:i,totalAmount:value,installmentAmount:amount,dueDate:d,paidDate:paid?d:null));}await _save();if(mounted)setState((){});}

  Future<void> _recurring()async{final desc=TextEditingController();final amount=TextEditingController();final count=TextEditingController(text:'12');String category='Outros';final ok=await showDialog<bool>(context:context,builder:(ctx)=>AlertDialog(title:const Text('Despesa recorrente'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:desc,decoration:const InputDecoration(labelText:'Descrição')),TextField(controller:amount,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Valor mensal',prefixText:'R\$ ')),TextField(controller:count,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Meses')),DropdownButtonFormField<String>(initialValue:category,items:expenseCategories.map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v){if(v!=null)category=v;},decoration:const InputDecoration(labelText:'Categoria'))]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('CANCELAR')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('CRIAR'))]));final value=double.tryParse(amount.text.replaceAll(',','.'));final n=int.tryParse(count.text);if(ok!=true||desc.text.trim().isEmpty||value==null||value<=0||n==null||n<1)return;final group=DateTime.now().microsecondsSinceEpoch.toString();for(var i=0;i<n;i++){final due=DateTime(DateTime.now().year,DateTime.now().month+i,DateTime.now().day);final d=DateFormat('yyyy-MM-dd').format(due);final paid=due.isBefore(DateTime.now())||DateUtils.isSameDay(due,DateTime.now());items.add(MoneyTransaction(id:'r-$group-$i',date:d,description:desc.text.trim(),category:category,amount:value,income:false,paymentStatus:paid?'paid':'pending',isRecurring:true,recurrenceGroupId:group,recurrenceFrequency:'monthly',recurrenceStartDate:d,dueDate:d,paidDate:paid?d:null));}await _save();if(mounted)setState((){});}

  Future<void> _toggle(MoneyTransaction x)async{x.paymentStatus=x.isPaid?'pending':'paid';x.paidDate=x.isPaid?null:DateFormat('yyyy-MM-dd').format(DateTime.now());await _save();if(mounted)setState((){});}
  Future<void> _delete(MoneyTransaction x)async{String scope='one';if(x.isInstallment||x.isRecurring){scope=await showDialog<String>(context:context,builder:(ctx)=>AlertDialog(title:const Text('Excluir'),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,'one'),child:const Text('SOMENTE ESTA')),TextButton(onPressed:()=>Navigator.pop(ctx,'future'),child:const Text('ESTA E PRÓXIMAS')),FilledButton(onPressed:()=>Navigator.pop(ctx,'all'),child:const Text('TODA A SÉRIE'))]))??'cancel';}if(scope=='cancel')return;items.removeWhere((e){if(scope=='one')return e.id==x.id;if(x.isInstallment)return e.installmentGroupId==x.installmentGroupId&&(scope=='all'||e.installmentNumber>=x.installmentNumber);if(x.isRecurring)return e.recurrenceGroupId==x.recurrenceGroupId&&(scope=='all'||e.date.compareTo(x.date)>=0);return false;});await _save();if(mounted)setState((){});}

  @override Widget build(BuildContext context){if(loading)return const Center(child:CircularProgressIndicator());final current=_month(month);final income=_sum(current,true,paid:true);final expense=_sum(current,false,paid:true);final projectedIncome=_sum(current,true);final projectedExpense=_sum(current,false);final categories=<String,double>{};for(final x in current.where((e)=>!e.income))categories[x.category]=(categories[x.category]??0)+x.amount;final next=DateTime(month.year,month.month+1);return SafeArea(child:ListView(padding:const EdgeInsets.all(16),children:[Row(children:[Expanded(child:Text('Financeiro',style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold))),FilledButton.icon(onPressed:_addMenu,icon:const Icon(Icons.add),label:const Text('Adicionar'))]),AppCard(child:Row(children:[IconButton(onPressed:()=>setState(()=>month=DateTime(month.year,month.month-1)),icon:const Icon(Icons.chevron_left)),Expanded(child:Text(DateFormat('MMMM yyyy','pt_BR').format(month),textAlign:TextAlign.center,style:const TextStyle(fontSize:18,fontWeight:FontWeight.bold))),IconButton(onPressed:()=>setState(()=>month=DateTime(month.year,month.month+1)),icon:const Icon(Icons.chevron_right))])),Row(children:[Expanded(child:_metric('Entradas realizadas',income)),Expanded(child:_metric('Despesas realizadas',expense))]),Row(children:[Expanded(child:_metric('Saldo atual',_balance())),Expanded(child:_metric('Resultado do mês',income-expense))]),AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Compromissos e previsão',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),Text('Comprometido: ${_money(_committed(month))}'),Text('Entradas previstas: ${_money(projectedIncome)}'),Text('Despesas previstas: ${_money(projectedExpense)}'),Text('Saldo projetado: ${_money(projectedIncome-projectedExpense)}'),Text('Próximo mês comprometido: ${_money(_committed(next))}'),const SizedBox(height:6),const Text('Valores projetados são estimativas baseadas nos lançamentos cadastrados.')])) ,if(categories.isNotEmpty)AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Distribuição das despesas',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),...categories.entries.map((e)=>ListTile(contentPadding:EdgeInsets.zero,title:Text(e.key),trailing:Text(_money(e.value))))])),const SizedBox(height:8),Text('Movimentações',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.bold)),if(current.isEmpty)const AppCard(child:Text('Nenhuma movimentação neste mês.')),...current.map((x)=>AppCard(child:ListTile(contentPadding:EdgeInsets.zero,title:Text(x.description),subtitle:Text('${x.category} • ${x.paymentStatus}${x.isInstallment?' • ${x.installmentNumber}/${x.totalInstallments}':''}${x.isRecurring?' • recorrente':''}'),trailing:PopupMenuButton<String>(onSelected:(v){if(v=='pay')_toggle(x);if(v=='delete')_delete(x);},itemBuilder:(_)=>const[PopupMenuItem(value:'pay',child:Text('Marcar pago/previsto')),PopupMenuItem(value:'delete',child:Text('Excluir'))]))))]));}
  Widget _metric(String label,double value)=>AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(_money(value),style:const TextStyle(fontWeight:FontWeight.bold)),Text(label,style:Theme.of(context).textTheme.bodySmall)]));
}
